    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nenum RefundStatus {\n  APPROVED\n  DENIED\n  ESCALATED\n}\n\nenum RefundReason {\n  DAMAGED\n  FAULTY\n  WRONG_ITEM\n  NOT_DELIVERED\n  MISSING_ITEM\n  OTHER\n}\n\nenum DecisionSource {\n  POLICY\n  AI\n  HUMAN\n}\n\nmodel Customer {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orders         Order[]\n  refundRequests RefundRequest[]\n}\n\nmodel Product {\n  id          String  @id @default(uuid())\n  name        String\n  description String?\n  sku         String  @unique\n  price       Decimal @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orderItems OrderItem[]\n}\n\nmodel Order {\n  id          String      @id @default(uuid())\n  orderNumber String      @unique\n  customerId  String\n  status      OrderStatus\n  totalAmount Decimal     @db.Decimal(10, 2)\n  orderedAt   DateTime\n  deliveredAt DateTime?\n\n  customer       Customer        @relation(fields: [customerId], references: [id])\n  items          OrderItem[]\n  refundRequests RefundRequest[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  productId String\n  quantity  Int\n  unitPrice Decimal @db.Decimal(10, 2)\n\n  // The exact variant sent to the customer.\n  // Example: size = \"30\", color = \"Black\"\n  size  String?\n  color String?\n\n  order   Order   @relation(fields: [orderId], references: [id])\n  product Product @relation(fields: [productId], references: [id])\n}\n\nmodel RefundRequest {\n  id          String       @id @default(uuid())\n  customerId  String\n  orderId     String\n  reason      RefundReason\n  description String\n  amount      Decimal      @db.Decimal(10, 2)\n\n  customer Customer @relation(fields: [customerId], references: [id])\n  order    Order    @relation(fields: [orderId], references: [id])\n\n  decision  RefundDecision?\n  auditLogs AuditLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel RefundDecision {\n  id              String         @id @default(uuid())\n  refundRequestId String         @unique\n  status          RefundStatus\n  source          DecisionSource\n  reason          String\n  confidence      Float?\n\n  refundRequest RefundRequest @relation(fields: [refundRequestId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\nmodel AuditLog {\n  id              String @id @default(uuid())\n  refundRequestId String\n  action          String\n  details         Json?\n\n  refundRequest RefundRequest @relation(fields: [refundRequestId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n",
